<?php/** * Created by PhpStorm. * User: zy * Date: 2020/3/4 * Time: 15:31 */namespace App\Http\Controllers\V1\CategoryTemplate;use App\Exceptions\Error;use App\Http\Controllers\V1\BaseController;use CrsSdk\Shop\CategoryTemplate;use Exception;use Illuminate\Http\Request;use Illuminate\Support\Facades\Log;use Illuminate\Validation\ValidationException;class EditController extends BaseController{    /**     * @param Request $request     *     * @return array     * @throws ValidationException     */    public function index(Request $request)    {        $input                  = $this->getParams($request);        $input['enterprise_id'] = $this->enterpriseId;        try {            $res = (new CategoryTemplate())->categoryEdit($input);            // 日志记录            $this->writeOperatorLog('修改【' . $input['id'] . '】分类');        } catch (Error $error) {            Log::info('修改分类失败', $error->data);            notice(100000, [$error->getMessage()]);        } catch (Exception $e) {            Log::info('修改分类失败' . $e->getMessage(), $input);            notice(100000, [$e->getMessage()]);        }        return success($res);    }    /**     * 验证数据     * @param $request     * @return array     * @throws ValidationException     */    protected function getParams($request)    {        // 验证参数        $rule = [            'id'      => 'required|integer',            'name'    => 'string',            'is_show' => 'integer|in:0,1',            'pic'     => 'string'        ];        $messages = [            'id.*'      => '分类不存在',            'name.*'    => '分类名称不能为空',            'pic.*'     => '分类图片不能为空',            'is_show.*' => '是否显示类型有误',        ];        $input = $this->validate($request, $rule, $messages);        if (!isset($input['name']) && !isset($input['pic']) && !isset($input['is_show'])) {            notice(2200000, ['修改必须传一个参数']);        }        return $input;    }}